/* TP_ROUTER — single source of truth for every internal URL.
 * URL shapes (generated by urlFor, parsed by parse):
 *   /                                    → home (trucks index, no filter)
 *   /trucks/{category}                   → category page
 *   /trucks/{make}                       → make page
 *   /trucks/{category}/{make}            → category + make
 *   /trucks/{make}/{model}               → make + model
 *   /trucks/{category}/{make}/{model}    → full drill-down
 *   /search?q=&sort=&mode=&page=&...     → anything with non-path state
 *   /listing/{id}                        → listing detail
 *   /login, /register, /forgot-password,
 *   /reset-password?token=...            → auth pages
 *
 * Any of the above also accepts hash form:  /#/trucks/peterbilt
 * Query params may also be supplied as /search?category=&make=&model=
 * (slugs) so a search URL can recreate the exact filtered state.
 */
(function () {
  "use strict";

  /* Top-level "info / marketing" views. They render as real pages but carry
   * no search state, so their URL is exactly "/{slug}". */
  var STATIC_VIEWS = [
    "sell", "financing", "advertising", "dealers", "watch-list", "values",
    "shipping", "market-reports", "hosted-websites", "want-to-buy",
    "email-signup", "brands", "legal", "returns", "subscriptions", "alerts",
    "dealer-portal", "sitemap",
  ];

  function slugify(s) {
    if (s == null) return "";
    return String(s)
      .trim()
      .toLowerCase()
      .replace(/&/g, "and")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "");
  }

  function slugToUpper(slug) {
    return String(slug || "")
      .trim()
      .toUpperCase();
  }

  function enc(s) {
    return s == null ? "" : encodeURIComponent(String(s));
  }

  /* Deployment sub-path, "" for a root install (Apache/Render/Docker) and
   * "/truckpaper" when the same bundle is served from GitHub Pages project
   * sites. Written into js/config.js by the build; never set by hand. */
  function basePath() {
    if (typeof window === "undefined" || !window.TP_BASE) return "";
    return String(window.TP_BASE).replace(/\/+$/, "");
  }

  function urlFor(state) {
    state = state || {};
    const base = basePath();

    /* Detail page wins over every other shape. */
    if (state.view === "detail" || state.id != null) {
      const id = Number(state.id);
      if (!Number.isFinite(id) || id <= 0) return base + "/";
      return base + "/listing/" + id;
    }

    /* Info / marketing pages — only when no search/filter state is present. */
    const hasQueryState =
      !!state.keyword || !!state.category || !!state.make || !!state.model ||
      !!state.condition || !!state.year || !!state.state || !!state.sort || !!state.mode ||
      !!state.dealer || !!state.specs || !!state.ranges ||
      state.pmin != null || state.pmax != null;
    if (!hasQueryState && state.view && STATIC_VIEWS.indexOf(state.view) !== -1) {
      return base + "/" + state.view;
    }

    /* Auth pages — only when no search/filter state is present. Without this
     * guard, an action taken from an auth page (header search, filter checkbox,
     * sort select) merges into currentState and urlFor would swallow it into
     * /login instead of producing a real results URL. */
    if (!hasQueryState && state.view === "login") return base + "/login";
    if (!hasQueryState && state.view === "register") return base + "/register";
    if (!hasQueryState && state.view === "forgot") return base + "/forgot-password";
    if (!hasQueryState && state.view === "reset") {
      return base + "/reset-password" + (state.token ? "?token=" + enc(state.token) : "");
    }

    const cat = state.category ? slugify(state.category) : "";
    const make = state.make ? slugify(state.make) : "";
    const model = state.model ? slugify(state.model) : "";
    const hasPath = !!(cat || make || model);

    const q = [];
    if (state.keyword) q.push("q=" + enc(state.keyword));
    if (state.condition) q.push("condition=" + enc(state.condition));
    if (state.year) q.push("year=" + enc(state.year));
    if (state.state) q.push("state=" + enc(state.state));
    if (state.dealer) q.push("dealer=" + enc(state.dealer));
    if (state.sort) q.push("sort=" + enc(state.sort));
    if (state.mode) q.push("mode=" + enc(state.mode));
    if (state.pmin != null && state.pmin !== "") q.push("pmin=" + Number(state.pmin));
    if (state.pmax != null && state.pmax !== "") q.push("pmax=" + Number(state.pmax));
    if (state.specs) {
      Object.keys(state.specs).forEach(function (k) {
        const v = state.specs[k];
        if (v == null || v === "") return;
        q.push("sp_" + enc(k) + "=" + enc(v));
      });
    }
    if (state.ranges) {
      Object.keys(state.ranges).forEach(function (k) {
        const r = state.ranges[k];
        if (!r || (r.min == null && r.max == null)) return;
        q.push("r_" + enc(k) + "=" +
          (r.min != null ? Number(r.min) : "") + ".." + (r.max != null ? Number(r.max) : ""));
      });
    }
    if (state.page && state.page > 1) q.push("page=" + Number(state.page));

    let path;
    if (hasPath) {
      path = "/trucks" + (cat ? "/" + cat : "") + (make ? "/" + make : "") + (model ? "/" + model : "");
    } else if (q.length) {
      path = "/search";
    } else {
      return "/";
    }
    return base + path + (q.length ? "?" + q.join("&amp;").replace(/&amp;/g, "&") : "");
  }

  /* Parse the current location into { segs, params, isHash }.
   * Accepts clean paths, hash routes (#/trucks/...), and query strings. */
  function parse() {
    const hash = window.location.hash;
    let path, qs;
    const isHash = !!(hash && hash.indexOf("#/") === 0);
    if (isHash) {
      const h = hash.slice(1); /* "/trucks/..." or "/search?..." */
      const qi = h.indexOf("?");
      path = qi === -1 ? h : h.slice(0, qi);
      qs = qi === -1 ? "" : h.slice(qi + 1);
    } else {
      path = window.location.pathname;
      /* Drop the deployment sub-path so /truckpaper/trucks/kenworth and
       * /trucks/kenworth parse to the same segs. No-op on a root install. */
      const base = basePath();
      if (base && path.indexOf(base + "/") === 0) path = path.slice(base.length);
      else if (base && path === base) path = "/";
      qs = window.location.search.replace(/^\?/, "");
    }
    const segs = path.split("/").filter(Boolean);
    const params = new URLSearchParams(qs);
    return { segs, params, isHash };
  }

  /* Prefix a site-relative URL with the deployment sub-path. Idempotent, and
   * a no-op on a root install, so it is safe to call on every navigation. */
  function withBase(url) {
    const u = String(url == null ? "" : url);
    if (u.charAt(0) !== "/" || u.charAt(1) === "/") return u;
    const base = basePath();
    if (!base || u === base || u.indexOf(base + "/") === 0) return u;
    return base + u;
  }

  function navigate(url, opts) {
    opts = opts || {};
    const u = withBase(url == null || url === "" ? "/" : url);
    /* No-op navigation: same path+query as where we already are. Replace
     * instead of push so every click on an active link doesn't pile up a
     * duplicate history entry (back would appear stuck). */
    const sameUrl = u === window.location.pathname + window.location.search;
    if (opts.replace || sameUrl) {
      window.history.replaceState(null, "", u);
    } else {
      window.history.pushState(null, "", u);
    }
    if (opts.notify !== false && onChange) onChange(u, opts);
    if (opts.scrollTop) window.scrollTo(0, 0);
    return u;
  }

  let onChange = null;
  function onRouteChange(cb) {
    onChange = cb;
    let lastHref = "";
    /* popstate AND hashchange can both fire for one URL change; render only
     * once so back/forward never doubles the work. */
    function fire() {
      const href = window.location.href;
      if (href === lastHref) return;
      lastHref = href;
      if (onChange) onChange(href, { back: true });
    }
    window.addEventListener("popstate", fire);
    window.addEventListener("hashchange", fire);
  }

  window.TP_ROUTER = {
    slugify: slugify,
    slugToUpper: slugToUpper,
    urlFor: urlFor,
    parse: parse,
    navigate: navigate,
    withBase: withBase,
    onRouteChange: onRouteChange,
    enc: enc,
  };
})();